public class BinarySearchBasics {

    // 1. 标准二分查找
    public int binarySearch(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2; // 防溢出
            if (nums[mid] == target) {
                return mid;
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }

    // 2. 左边界二分：找第一个等于 target 的位置
    public int leftBound(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                // nums[mid] >= target 时也收缩右界
                // 不返回，继续往左找
                right = mid - 1;
            }
        }
        // 循环结束：left 是第一个 >= target 的位置
        if (left >= nums.length || nums[left] != target) return -1;
        return left;
    }

    // 3. 右边界二分：找最后一个等于 target 的位置
    public int rightBound(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] <= target) {
                // nums[mid] <= target 时也收缩左界
                // 不返回，继续往右找
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        // 循环结束：right 是最后一个 <= target 的位置
        if (right < 0 || nums[right] != target) return -1;
        return right;
    }

    // 4. 搜索插入位置（lower_bound）
    public int searchInsert(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return left; // 第一个 >= target 的位置，即插入位置
    }

    // 5. 旋转排序数组中查找（LeetCode 33）
    public int searchRotated(int[] nums, int target) {
        int left = 0, right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) return mid;

            if (nums[left] <= nums[mid]) {
                // 左半有序
                if (target >= nums[left] && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else {
                // 右半有序
                if (target > nums[mid] && target <= nums[right]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }
        return -1;
    }

    // 6. 查找峰值（LeetCode 162）
    public int findPeakElement(int[] nums) {
        int left = 0, right = nums.length - 1;
        while (left < right) { // 注意是 < 不是 <=
            int mid = left + (right - left) / 2;
            if (nums[mid] < nums[mid + 1]) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    // 7. 二分答案：最小化最大值（LeetCode 410 Split Array Largest Sum）
    public int splitArray(int[] nums, int k) {
        int left = 0, right = 0;
        for (int num : nums) {
            left = Math.max(left, num); // 下界：单个元素最大值
            right += num;               // 上界：所有元素之和
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canSplit(nums, k, mid)) {
                right = mid;    // 可行，尝试更小的最大和
            } else {
                left = mid + 1; // 不可行，增大下界
            }
        }
        return left;
    }

    private boolean canSplit(int[] nums, int k, int maxSum) {
        int count = 1, currentSum = 0;
        for (int num : nums) {
            if (currentSum + num > maxSum) {
                count++;
                currentSum = num;
            } else {
                currentSum += num;
            }
        }
        return count <= k;
    }
}
